#!/bin/bash
cd /tmp/claude-1000/-home-kristihack-Documents-MANRUST/6669f544-3acf-4c2d-bf09-25e9e377451d/scratchpad
EXTRAQ="-nic user,model=virtio-net-pci -virtfs local,path=/tmp/claude-1000/-home-kristihack-Documents-MANRUST/6669f544-3acf-4c2d-bf09-25e9e377451d/scratchpad/repo2,mount_tag=repo,security_model=none,readonly=on" DISKS="/home/kristihack/Documents/MANRUST/lfs/.vmtest/ft.qcow2:qcow2" EXTRA="systemd.debug_shell=ttyS1" nohup setsid ./uefi.sh FT /tmp/claude-1000/-home-kristihack-Documents-MANRUST/6669f544-3acf-4c2d-bf09-25e9e377451d/scratchpad/j-vars.fd /tmp/claude-1000/-home-kristihack-Documents-MANRUST/6669f544-3acf-4c2d-bf09-25e9e377451d/scratchpad/repo2/kernel/vmlinuz-7.3.0-rc7 >FT.qemuerr 2>&1 &
for i in $(seq 40); do sleep 3; python3 -I ser.py FT.dbg "echo READY-\$((6*7))" 2 2>/dev/null | grep -q READY-42 && break; done
python3 -I ser.py FT.dbg "mkdir -p /mnt/repo; mount -t 9p -o trans=virtio,ro repo /mnt/repo; install -m755 /mnt/repo/gcc-new /usr/bin/gnome-control-center; sleep 25; loginctl unlock-sessions; P=\$(pgrep -u MANInstaller -x gnome-shell | head -1); tr '\\0' '\\n' < /proc/\$P/environ | grep -E '^(XDG_|DBUS_|WAYLAND_|DISPLAY|HOME|LANG|PATH)' > /tmp/sess.env; runuser -u MANInstaller -- env \$(cat /tmp/sess.env | tr '\\n' ' ') gsettings set org.gnome.desktop.screensaver lock-enabled false; runuser -u MANInstaller -- env \$(cat /tmp/sess.env | tr '\\n' ' ') gsettings set org.gnome.desktop.session idle-delay 0; md5sum /usr/bin/gnome-control-center" 40 | grep gnome-control
